Translate("zhCN", "caverns-of-time", {
	title = "时光之穴",
	sections = {
		{
			title = "概述",
			text = [=[在{link:tanaris}塔纳利斯{/link}东部的山脉中，一个巨大的洞穴向岩石深处敞开。它被称为时光之穴。古老的传说称，这里是{red:bronze-dragonflight}青铜龙{/red}的巢穴，也是它们的主人、永恒者{red:nozdormu}诺兹多姆{/red}的居所，泰坦赋予他守护时间之路的职责。这个时代的旅人中，还没有人讲述过里面有什么。]=],
		},
	},
})

Translate("zhCN", "valley-of-the-watchers", {
