Translate("zhCN", "the-gaping-chasm", {
	title = "大裂口",
	aliases = { "大裂口" },
	sections = {
		{
			title = "概述",
			text = [=[大裂口是{link:gadgetzan}加基森{/link}东南沙地上的一道深深的裂谷。森提帕尔在里面建了第二座虫巢，这让地精们明白，虫子占据的不是沙漠的一个区域，而是两个。初级勘测员斯克里姆尚克出发去绘制裂谷的地图，再也没有回来。人们只找到了他的勘测装备。一台{link:gnomes}侏儒{/link}的寻路机器人也坠毁在裂谷边缘附近，远离它在{link:booty-bay}藏宝海湾{/link}的制造者。]=],
		},
	},
})

