Translate("zhCN", "gadgetzan-water-company", {
	title = "加基森水务公司",
	aliases = { "加基森水务", "水务公司" },
	sections = {
		{
			title = "概述",
			text = [=[加基森水务公司维护着{link:gadgetzan}加基森{/link}的水井和水泵，在沙漠中，这使它成为{link:tanaris}塔纳利斯{/link}最重要的生意。它的工程师挖掘水洞，它的水龙头操作员管理水塔，它的勘测员在沙漠中寻找新的泉水。它卖水，就像它卖别的一切东西一样，都是有价钱的。]=],
		},
		{
			title = "如今",
			text = [=[公司正处于战争之中。{link:wastewander-nomads}荒漠流浪者{/link}夺走了它在城墙外几乎所有的水井，杀害了它的工人，偷走了它的储备。{link:chief-engineer-bilgewhizzle}首席工程师沙克斯·比格维兹{/link}悬赏游牧者及其首领{link:caliph-scorpidsting}卡利夫·斯科比斯汀{/link}，水龙头操作员鲁格兰克特则为每一个从他们手中夺回的水袋付钱。与此同时，{link:senior-surveyor-fizzledowser}高级勘探员菲兹杜瑟{/link}派初级勘测员出去寻找新的水源，而他们发现了比游牧者更糟的东西。虫子正在吸干西方的公共水池，公司的一名勘测员已经死在了{link:the-gaping-chasm}大裂口{/link}。这家通常会把所知之事拿去出售的公司，选择了把关于虫子的报告免费送给任何愿意读的人。]=],
		},
		{
			title = "组织",
			text = [=[• {b}{link:chief-engineer-bilgewhizzle}首席工程师沙克斯·比格维兹{/link}{/b}领导公司争夺水井的战斗。
• {b}{link:senior-surveyor-fizzledowser}高级勘探员菲兹杜瑟{/link}{/b}领导新水源的勘测。
• {b}水龙头操作员鲁格兰克特{/b}管理水塔和悬赏。
• {b}{link:steamwheedle-port}热砂港{/link}的{link:security-chief-bilgewhizzle}安全主管吉罗姆·比格维兹{/link}{/b}拥有水务公司保安的头衔。]=],
		},
	},
})

Translate("zhCN", "wastewander-nomads", {
	title = "荒漠流浪者",
	aliases = { "荒漠流浪者", "游牧者" },
	sections = {
		{
			title = "概述",
			text = [=[荒漠流浪者是{link:tanaris}塔纳利斯{/link}东部沙漠的亡命之徒。他们是强盗、窃贼和杀手，却做到了任何军队都没能做到的事：他们从地精手中夺走了塔纳利斯的水。{link:gadgetzan}加基森{/link}城墙外几乎每一口井都归他们所有。他们用水袋把水运走，靠它过活，而建造这些水井的城镇却不得不购买能量源、支付赏{link:ginro-hearthkindle}金{/link}，才能把水井夺回来。]=],
		},
		{
			title = "等级",
			text = [=[• {b}强盗和窃贼{/b}占据{link:gadgetzan}加基森{/link}以东最近的水井。
• {b}盗贼、刺客和暗影法师{/b}是更强的等级，守在更远的东方和东南方。
• {b}{link:caliph-scorpidsting}卡利夫·斯科比斯汀{/link}{/b}统领着所有人。]=],
		},
		{
			title = "如今",
			text = [=[{link:gadgetzan-water-company}水务公司{/link}称他们为霸占者和杀人犯。公司雇用外人来削减他们的人数，并希望他们首领的死能最终把他们赶离水井。]=],
		},
		{ title = "未载", text = "没有任何编年史讲述荒漠流浪者从何而来，也没有讲述他们最初何时来到沙漠。" },
	},
})

Translate("zhCN", "southsea-pirates", {
	title = "南海海盗",
	aliases = { "南海", "南海海盗团" },
	sections = {
		{
			title = "概述",
			text = [=[南海海盗是南方海域的劫掠者。他们从隐秘的港湾出发，袭击{link:kalimdor}卡利姆多{/link}的商业海岸，最喜欢的猎物是{link:steamwheedle-cartel}热砂港{/link}的船只。在{link:tanaris}塔纳利斯{/link}，他们占据着{link:lost-rigger-cove}落帆海湾{/link}，那是{link:steamwheedle-port}热砂港{/link}以南海滩上的一座有围墙的城镇。他们的另一伙人则在{link:the-barrens}贫瘠之地{/link}的{link:ratchet}棘齿城{/link}以南的海岸上作乱。]=],
		},
		{
			title = "如今",
			text = [=[{link:lost-rigger-cove}落帆海湾{/link}的海盗偷走了{link:steamwheedle-port}热砂港{/link}的朗姆酒，还带着港口自己的船期表，上面标注着哪些船油水丰厚、哪些船顽强抵抗。他们的船长{link:andre-firebeard}安德雷·费尔比德{/link}同时受到热砂港和{link:gadgetzan}加基森{/link}的通缉。据说集团曾经花钱让海盗放过它的船只，而海盗们已经开始拿了钱照抢不误。]=],
		},
	},
})

Translate("zhCN", "sandfury-trolls", {
	title = "沙怒巨魔",
	aliases = { "沙怒", "沙怒部族" },
	sections = {
		{
			title = "概述",
			text = [=[沙怒是沙漠中的{link:trolls}巨魔{/link}。他们的城市是位于{link:tanaris}塔纳利斯{/link}西北部的{red:zul-farrak}祖尔法拉克{/red}，他们的战士在{link:sandsorrow-watch}流沙岗哨{/link}等前哨中警戒。他们以残忍著称，也以一种能让死者复起为他们效力的黑暗秘术著称。他们崇拜加兹瑞拉，一头他们从城市中心的圣池中召唤出来的巨大九头蛇。]=],
		},
		{
			title = "他们的技艺",
			text = [=[沙怒巨魔用沙漠的砂岩制作一种回火剂，识货的铁匠对它十分珍视。圣甲虫在他们的城市里成群结队，那里没有{link:trolls}巨魔{/link}为了甲壳去猎杀它们。很久以前被带到那里的先知摩沙鲁的古老石板，由他们的祭司保管着。]=],
		},
		{
			title = "如今",
			text = [=[沙怒巨魔在沙漠中没有朋友。地精铁匠和学者花钱购买能从他们城市里弄出来的东西，一队队寻宝者进去寻找城中的财富。并不是所有人都能出来。]=],
		},
		{
			title = "未载",
			text = [=[这个时代没有任何编年史讲述沙怒巨魔占据祖尔法拉克有多久，也没有讲述他们与其他{link:trolls}巨魔{/link}部族有着怎样的关系。]=],
		},
	},
})

Translate("zhCN", "marin-noggenfogger", {
	title = "马林·诺格弗格",
	subtitle = "加基森之主",
	found = "加基森，城镇中心",
	hint = "寻找治理加基森的地精。",
	allegiance = "加基森 · 热砂港",
	aliases = { "诺格弗格" },
	sections = {
		{
			title = "概述",
			text = [=[马林·诺格弗格是{link:gadgetzan}加基森{/link}的地精主人，这座城镇是{link:steamwheedle-cartel}热砂港{/link}在{link:tanaris}塔纳利斯沙漠{/link}中建起的。{link:baron-revilgaz}大财主里维加兹{/link}统治着{link:booty-bay}藏宝海湾{/link}，{link:gazlowe}加兹鲁维{/link}照管着{link:ratchet}棘齿城{/link}，而诺格弗格掌管着集团的沙漠城镇。他焦躁不安，总是口渴，又总在寻找下一个了不起的点子。就连他的朋友也说他古怪。]=],
		},
		{
			title = "意义",
			text = [=[{link:gadgetzan}加基森{/link}坐落在方圆许多里格之内唯一安全的水源之上，它的主人统治着南方每一条道路的交汇点。在诺格弗格治下，这座城镇一直是中立之地。{link:alliance}联盟{/link}和{link:horde}部落{/link}都在它的城墙后休息，城里的打手维持着和平。他的名字还因以他命名的药剂而远播沙漠之外，他打算靠这种药剂发家致富。]=],
		},
		{
			title = "事迹",
			text = [=[• 他为{link:steamwheedle-port}热砂港{/link}治理{link:gadgetzan}加基森{/link}。
• 他听说有一种奇特的沙漠生物把水储存在腺体中，便着手用它们酿一种饮料。
• 在朋友{link:sprinkle}斯普琳科{/link}的帮助下，他创造了诺格弗格药剂。]=],
		},
		{
			title = "未载",
			text = [=[没有任何编年史讲述诺格弗格是如何成为{link:gadgetzan}加基森{/link}的统治者的，也没有讲述在他之前由谁统治。]=],
		},
	},
	chapters = {
		{
			title = "口渴的地精",
			hint = "给口渴的加基森之主带去仙人掌园中藏着的东西。",
			text = [=[诺格弗格渴得不得了，几乎到了绝望的地步。他听说过{link:thistleshrub-valley}灌木谷{/link}的露水收集者，便推想它们腺体中的水或许终于能让他解渴。当一个装满了水的腺体被送到他面前时，他立刻喝了下去。味道糟透了。他差点就此放弃，直到他认定，这么难喝的饮料至少应该有点劲头。]=],
		},
		{
			title = "药剂",
			hint = "帮助地精完善他的饮料。",
			text = [=[{link:gadgetzan}加基森{/link}的厨师{link:sprinkle}斯普琳科{/link}知道一个秘密：{link:the-hinterlands}辛特兰{/link}一个小湖的水下长着一种紫色的蘑菇。把它磨成粉，掺进露水里，这种酒就不只是能喝，而是美妙无比了。诺格弗格宣称他要靠它赚上几百万。当他听说自己欠了斯普琳科一个人情时，他说她真会开玩笑。]=],
		},
	},
	mentions = {
		{ text = "品味不凡" },
		{ text = "{link:sprinkle}斯普琳科{/link}的秘密配料" },
		{ text = "给马林的货物" },
	},
	bonds = {
		{ id = "sprinkle", name = "斯普琳科", note = "他的朋友和厨师" },
		{ id = "chief-engineer-bilgewhizzle", name = "首席工程师沙克斯·比格维兹", note = "掌管城镇的水" },
		{ id = "baron-revilgaz", name = "大财主里维加兹", note = "为同一个集团统治藏宝海湾" },
		{ id = "gazlowe", name = "加兹鲁维", note = "为同一个集团统治棘齿城" },
	},
})

Translate("zhCN", "yeh-kinya", {
	title = "叶基亚",
	subtitle = "巨魔预言的学者",
	found = "热砂港",
	hint = "寻找在热砂港货箱之间研究古老预言的巨魔。",
	allegiance = "未知",
	sections = {
		{
			title = "概述",
			text = [=[叶基亚是一个生活在{link:steamwheedle-port}热砂港{/link}地精之中的{link:trolls}巨魔{/link}。他比大多数人都更了解他的族人的古老传说，尤其是关于已死的血之神——夺魂者{link:hakkar}哈卡{/link}的传说。他说他不相信哈卡归来的故事。但他确实相信这位神祇的精华蕴含着强大的力量，并且已经着手收集它。]=],
		},
		{
			title = "意义",
			text = [=[正是叶基亚让{link:hakkar}哈卡{/link}之卵的事情运转起来。通过野兽的灵魂、一位已故先知的石板，以及藏在一座{link:trolls}巨魔{/link}城市中的一枚蛋，他得知了如何捕获并保存夺魂者的精华。他说要让它远离那些会滥用它的人。并不是每个人都相信他。]=],
		},
		{
			title = "事迹",
			text = [=[• 他寻找{link:feralas}菲拉斯{/link}的谷地尖啸者的灵魂，他称它们是一位古神的亲族。
• 他从{red:zul-farrak}祖尔法拉克{/red}收集了先知摩沙鲁的前两块石板，并将它们合而为一。
• 他派人从{link:jintha-alor}辛萨罗{/link}取来一枚古老的蛋，那是{link:trolls}巨魔{/link}帝国的遗物。
• 他把蛋送进了{link:temple-of-atal-hakkar}阿塔哈卡神庙{/link}，神祇的精华在那里被捕获。]=],
		},
		{ title = "未载", text = "没有任何编年史讲述叶基亚来自哪个部族，也没有讲述他为何生活在地精之中。" },
	},
	chapters = {
		{
			title = "尖啸者之魂",
			hint = "把菲拉斯尖啸者的灵魂带给热砂港的巨魔。",
			text = [=[叶基亚想要谷地尖啸者的灵魂，因为他认为它们与一位古老的神祇有关。灵魂被带来之后，他讲述了一个古老的{link:trolls}巨魔{/link}预言：已死的神祇{link:hakkar}哈卡{/link}终有一天会回到这个世界。一些巨魔说这将带来荣耀。另一些则说，这将带来万物的终结。]=],
		},
		{
			title = "摩沙鲁的预言",
			hint = "把祖尔法拉克的先知石板带给巨魔。",
			text = [=[摩沙鲁的预言写在两块石板上，被带到了祖尔法拉克。一块由已死的{link:trolls}巨魔{/link}殉教者塞卡持有，另一块由圣池旁的水占师维蕾萨持有。叶基亚把两块石板合在一起，读出了其中的秘密：一枚古老的蛋可以容纳{link:hakkar}哈卡{/link}的精华。]=],
		},
		{
			title = "哈卡之卵",
			hint = "把蛋带进沉没的神庙，再把装满的蛋带回来。",
			text = [=[蛋在{link:jintha-alor}辛萨罗{/link}被找到，被带进了堕落之神的圣殿。{link:avatar-of-hakkar}哈卡的化身{/link}现身，又倒下了，它的精华被封进了蛋中。当蛋回到{link:tanaris}塔纳利斯{/link}时，它在生命的气息中颤动。叶基亚似乎受了震动，他发誓要保护它，不让它落入邪恶之手。]=],
		},
		{
			title = "失落的石板",
			hint = "听听热砂港的矮人发现了什么。",
			text = [=[一位站在离叶基亚几步远处的{link:dwarves}矮人{/link}勘探者，也研究过这个预言。他说摩沙鲁的石板有六块，而不是两块，而那个{link:trolls}巨魔{/link}并没有说出全部真相。]=],
		},
	},
	mentions = {
		{ text = "远古之卵" },
	},
	bonds = {
		{ id = "hakkar", name = "哈卡", note = "他收集其精华的神祇" },
		{ id = "avatar-of-hakkar", name = "哈卡的化身", note = "其精华装满了他的蛋" },
		{ id = "prospector-ironboot", name = "勘查员詹斯·铁靴", note = "怀疑他的话" },
	},
})

Translate("zhCN", "senior-surveyor-fizzledowser", {
	title = "高级勘探员菲兹杜瑟",
	subtitle = "加基森水务公司",
	found = "加基森，城镇西侧",
	hint = "寻找为新水源勘测沙漠的地精。",
	allegiance = "加基森水务公司 · 加基森",
	aliases = { "菲兹杜瑟" },
	sections = {
		{
			title = "概述",
			text = [=[高级勘探员菲兹杜瑟为{link:gadgetzan-water-company}加基森水务公司{/link}领导沙漠中的寻水工作。由于{link:wastewander-nomads}游牧者{/link}占据着水井，他派初级勘测员带着探水装置进入沙漠，寻找公共水池和泉水。他们发现的，是一种远比任何游牧者都大的威胁。]=],
		},
		{
			title = "意义",
			text = [=[菲兹杜瑟是第一个就{link:tanaris}塔纳利斯{/link}的虫子发出警报的地精。起初，他把关于奇怪的虫形生物吸水的报告当作{link:wastewander-nomads}游牧者{/link}的又一个把戏，不予理会。后来，他的勘测员开始死去。他的报告，以及{link:alchemist-pestlezugg}炼金师匹斯特苏格{/link}的报告，把{link:qiraji}异种蝎{/link}这个名字从{link:gadgetzan}加基森{/link}带到了{link:orgrimmar}奥格瑞玛{/link}和{link:darnassus}达纳苏斯{/link}。]=],
		},
		{
			title = "事迹",
			text = [=[• 他派一名勘测员去测试{link:sandsorrow-watch}流沙岗哨{/link}附近的水池，第一次虫子袭击就发生在那里。
• 他下令收集{link:the-noxious-lair}腐化之巢{/link}中虫子的身体部位以供研究。
• 他在{link:the-gaping-chasm}大裂口{/link}失去了他最得力的助手、初级勘测员斯克里姆尚克。
• 他违背自己这一行的所有习惯，同意免费分享关于虫子的报告。]=],
		},
	},
	chapters = {
		{
			title = "水源勘测",
			hint = "为水务公司汲取巨魔哨塔附近的水池。",
			text = [=[前往{link:sandsorrow-watch}流沙岗哨{/link}水池的勘测员遭到了一只从沙中钻出的生物的伏击。菲兹杜瑟承认他听说过这种生物。他过去不相信。现在他信了，并且担心这对公司意味着什么。]=],
		},
		{
			title = "斯克里姆尚克的救赎",
			hint = "查明在大裂口失踪的勘测员的下落。",
			text = [=[斯克里姆尚克进入了{link:the-gaping-chasm}大裂口{/link}，他最后的报告提到那里有更多的虫子。回来的只有他的勘测装备。菲兹杜瑟亲自整理了这个年轻地精的遗物。斯克里姆尚克留下的记录表明，这些虫子可能受某个第三方势力的控制。]=],
		},
		{
			title = "异种蝎的崛起",
			hint = "把关于虫子的报告带给各大城市的学者。",
			text = [=[{link:alchemist-pestlezugg}匹斯特苏格{/link}要求所有识字的人都看看这份报告。通常把知识卖个好价钱的菲兹杜瑟，抄了几份副本，送给他在各个首都认识的学者。敌人的名字就是从他们那里得知的。]=],
		},
	},
	mentions = {
		{ text = "{link:the-noxious-lair}腐化之巢{/link}调查" },
		{ text = "昆虫部位分析" },
	},
	bonds = {
		{ id = "alchemist-pestlezugg", name = "炼金师匹斯特苏格", note = "与他一同研究虫子" },
		{ id = "chief-engineer-bilgewhizzle", name = "首席工程师沙克斯·比格维兹", note = "水务公司的同僚" },
	},
})

Translate("zhCN", "chief-engineer-bilgewhizzle", {
	title = "首席工程师沙克斯·比格维兹",
	subtitle = "加基森水务公司",
	found = "加基森，水塔下",
	hint = "寻找掌管加基森之水的工程师。",
	allegiance = "加基森水务公司 · 加基森",
	sections = {
		{
			title = "概述",
